protected void addPathFile(File pathComponent) throws IOException {
    if (!pathComponents.contains(pathComponent)) {
        pathComponents.addElement(pathComponent);
    }

    if (pathComponent.isDirectory()) {
        return;
    }

    String manifestClasspath = readManifestClasspath(pathComponent);
    if (!manifestClasspath.isEmpty()) {
        addClasspathEntriesFromManifest(pathComponent, manifestClasspath);
    }
}

/**
 * Reads the manifest classpath entry from the given jar file.
 *
 * @param pathComponent the jar file from which to read the manifest.
 * @return the manifest's CLASSPATH attribute, or an empty string if none.
 * @throws IOException if reading the manifest fails.
 */
private String readManifestClasspath(File pathComponent) throws IOException {
    String absPathPlusTimeAndLength =
        pathComponent.getAbsolutePath() + pathComponent.lastModified() + "-" + pathComponent.length();
    String cachedClasspath = pathMap.get(absPathPlusTimeAndLength);
    if (cachedClasspath != null) {
        return cachedClasspath;
    }

    JarFile jarFile = null;
    try {
        jarFile = new JarFile(pathComponent);
        Manifest manifest = jarFile.getManifest();
        String classpath = manifest == null ? "" : manifest.getMainAttributes()
            .getValue(Attributes.Name.CLASS_PATH);
        if (classpath == null) {
            classpath = "";
        }
        pathMap.put(absPathPlusTimeAndLength, classpath);
        return classpath;
    } finally {
        if (jarFile != null) {
            jarFile.close();
        }
    }
}

/**
 * Adds classpath entries declared in the manifest of the given jar file.
 *
 * @param pathComponent the jar file whose manifest contains classpath entries.
 * @param manifestClasspath the manifest's CLASSPATH attribute value.
 * @throws IOException if resolving a classpath entry fails.
 */
private void addClasspathEntriesFromManifest(File pathComponent, String manifestClasspath)
    throws IOException {
    URL baseURL = FILE_UTILS.getFileURL(pathComponent);
    StringTokenizer st = new StringTokenizer(manifestClasspath);
    while (st.hasMoreTokens()) {
        String classpathElement = st.nextToken();
        URL libraryURL = new URL(baseURL, classpathElement);
        if (!libraryURL.getProtocol().equals("file")) {
            log("Skipping jar library " + classpathElement
                + " since only relative URLs are supported by this loader",
                Project.MSG_VERBOSE);
            continue;
        }
        String decodedPath = Locator.decodeUri(libraryURL.getFile());
        File libraryFile = new File(decodedPath);
        if (libraryFile.exists() && !isInPath(libraryFile)) {
            addPathFile(libraryFile);
        }
    }
}

