        Classifier classifier = extractClassifier(context);
        if (classifier != null) {
            Object found = findOperationInClassifier(classifier, opname);
            if (found != null) {
                return found;
            }
        }

        Namespace pack = extractNamespace(context, classifier);
        if (pack != null) {
            Object found = findOperationInNamespace(pack, opname);
            if (found != null) {
                return found;
            }
        }
