def _extract_scheme_info(key, elem, prefixes):
    """Extract scheme information for a property element and return a key-value tuple."""
    val = (elem.text or '').strip()
    if not val:
        return None
    scheme = elem.get('scheme') or None
    scheme_ns = None
    if scheme is not None:
        p, _, r = scheme.partition(':')
        if p and r:
            ns = prefixes.get(p)
            if ns:
                scheme_ns = ns
                scheme = r
    return key, (scheme_ns, scheme, val)


