def is_valid_scheme(scheme):
    """Check if scheme is a valid non-HTTP, non-empty string."""
    return scheme is not None and scheme.lower() not in ('http', 'https')


def is_isbn_scheme(scheme):
    """Check if scheme indicates ISBN."""
    return scheme.lower().startswith('isbn')


def extract_isbn_value(val):
    """Extract ISBN component from value."""
    return val.split(':')[-1]


def parse_identifier_part(identifier, val, refines):
    """Parse identifier using OPF 2 style scheme attribute or URN format."""
    idid = identifier.get('id')
    if not idid:
        return None, None

    refines_list = refines.get(idid, [])
    scheme = None
    lval = val.lower()

    # Check OPF 2 style scheme
    scheme = identifier.get(OPF('scheme'))
    if scheme and not lval.startswith('urn:'):
        if is_valid_scheme(scheme):
            scheme = scheme.lower()
            if is_isbn_scheme(scheme):
                scheme = 'isbn'
                val = extract_isbn_value(val)
                if not check_isbn(val):
                    return None, None
            return scheme, val
        return None, None

    # Handle URN format
    if lval.startswith('urn:'):
        val = val[4:]

    # Parse prefix:rest from URN
    prefix, _, rest = val.partition(':')
    if not prefix or not rest:
        return None, None

    if is_valid_scheme(prefix):
        prefix = prefix.lower()
        if is_isbn_scheme(prefix):
            prefix = 'isbn'
            rest = extract_isbn_value(rest)
            if not check_isbn(rest):
                return None, None
        return prefix, rest

    return None, None


