def media_property(cls):
    def _media(self):
        # Get the media property of the superclass, if it exists
        sup_cls = super(cls, self)
        try:
            base = sup_cls.media
        except AttributeError:
            base = Media()

        # Get the media definition for this class
        definition = getattr(cls, 'Media', None)
        if definition:
            extend = getattr(definition, 'extend', True)
            if extend:
                return _build_media_with_extension(base, definition, extend)
            else:
                return Media(definition)
        else:
            return base
    return property(_media)


def _build_media_with_extension(base, definition, extend):
    """
    Build media by combining base media with the current class's media,
    respecting the extend configuration.
    """
    if extend is True:
        m = base
    else:
        m = Media()
        for medium in extend:
            m = m + base[medium]
    return m + Media(definition)

class RegroupNode(Node):
    def __init__(self, target, expression, var_name):
        self.target, self.expression = target, expression
        self.var_name = var_name

    def _resolve_expression_for_obj(self, obj, context):
        # Temporarily sets obj in context under var_name and resolves expression
        context[self.var_name] = obj
        return self.expression.resolve(context, True)

    def render(self, context):
        obj_list = self.target.resolve(context, True)
        if obj_list is None:
            # target variable wasn't found in context; fail silently.
            context[self.var_name] = []
            return ''

        grouped = []
        for key, group in groupby(obj_list, lambda obj: self._resolve_expression_for_obj(obj, context)):
            grouped.append(GroupedResult(grouper=key, list=list(group)))

        context[self.var_name] = grouped
        return ''

def media_property(cls):
    def _media(self):
        # Get the media property of the superclass, if it exists
        sup_cls = super(cls, self)
        try:
            base = sup_cls.media
        except AttributeError:
            base = Media()

        # Get the media definition for this class
        definition = getattr(cls, 'Media', None)
        if definition:
            extend = getattr(definition, 'extend', True)
            if extend:
                return _build_media_with_extension(base, definition, extend)
            else:
                return Media(definition)
        else:
            return base
    return property(_media)


def _build_media_with_extension(base, definition, extend):
    """
    Build media by combining base media with the current class's media definition.
    Handles both default extension (True) and selective extension (list/tuple of media types).
    """
    if extend is True:
        m = base
    else:
        m = Media()
        for medium in extend:
            m = m + base[medium]
    return m + Media(definition)

