@Override
public boolean commit() throws LoginException {
  if (LOG.isDebugEnabled()) {
    LOG.debug("hadoop login commit");
  }

  if (!subject.getPrincipals(User.class).isEmpty()) {
    logAndReturnTrueIfDebug("using existing subject:" + subject.getPrincipals());
    return true;
  }

  Principal user = findUserInPriorityOrder();

  if (user != null) {
    addUserEntryAndCommit(user);
    return true;
  }

  LOG.error("Can't find user in " + subject);
  throw new LoginException("Can't find user name");
}

private void logAndReturnTrueIfDebug(String message) {
  if (LOG.isDebugEnabled()) {
    LOG.debug(message);
  }
}

private Principal findUserInPriorityOrder() throws LoginException {
  Principal user = null;

  if (isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
    user = getCanonicalUser(KerberosPrincipal.class);
    if (user != null) {
      logAndReturnTrueIfDebug("using kerberos user:" + user);
    }
  }

  if (!isSecurityEnabled() && user == null) {
    user = findUserFromEnvironmentOrProperties();
    if (user != null) {
      logAndReturnTrueIfDebug("using environment/property user:" + user);
    }
  }

  if (user == null) {
    user = getCanonicalUser(OS_PRINCIPAL_CLASS);
    if (user != null) {
      logAndReturnTrueIfDebug("using local user:" + user);
    }
  }

  return user;
}

private Principal findUserFromEnvironmentOrProperties() {
  String envUser = System.getenv(HADOOP_USER_NAME);
  if (envUser == null) {
    envUser = System.getProperty(HADOOP_USER_NAME);
  }
  return envUser == null ? null : new User(envUser);
}

private void addUserEntryAndCommit(Principal user) throws LoginException {
  logAndReturnTrueIfDebug("Using user: \"" + user + "\" with name " + user.getName());

  User userEntry;
  try {
    userEntry = new User(user.getName());
  } catch (Exception e) {
    throw (LoginException)(new LoginException(e.toString()).initCause(e));
  }

  logAndReturnTrueIfDebug("User entry: \"" + userEntry.toString() + "\"");
  subject.getPrincipals().add(userEntry);
}

