@Override
public boolean commit() throws LoginException {
  if (LOG.isDebugEnabled()) {
    LOG.debug("hadoop login commit");
  }

  if (!subject.getPrincipals(User.class).isEmpty()) {
    logAlreadyUsingSubject();
    return true;
  }

  Principal user = tryGetKerberosUser();
  user = tryGetEnvironmentOrSystemUser(user);
  user = tryGetOSPrincipalUser(user);

  return finalizeUserInSubject(user);
}

private void logAlreadyUsingSubject() {
  if (LOG.isDebugEnabled()) {
    LOG.debug("using existing subject:" + subject.getPrincipals());
  }
}

private Principal tryGetKerberosUser() {
  if (isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
    Principal user = getCanonicalUser(KerberosPrincipal.class);
    if (LOG.isDebugEnabled() && user != null) {
      LOG.debug("using kerberos user:" + user);
    }
    return user;
  }
  return null;
}

private Principal tryGetEnvironmentOrSystemUser(Principal existingUser) {
  if (existingUser == null && !isSecurityEnabled()) {
    String envUser = getEnvOrSystemProperty(HADOOP_USER_NAME);
    return envUser == null ? null : new User(envUser);
  }
  return existingUser;
}

private Principal tryGetOSPrincipalUser(Principal existingUser) {
  if (existingUser == null) {
    Principal user = getCanonicalUser(OS_PRINCIPAL_CLASS);
    if (LOG.isDebugEnabled() && user != null) {
      LOG.debug("using local user:" + user);
    }
    return user;
  }
  return existingUser;
}

private boolean finalizeUserInSubject(Principal user) throws LoginException {
  if (user == null) {
    LOG.error("Can't find user in " + subject);
    throw new LoginException("Can't find user name");
  }

  if (LOG.isDebugEnabled()) {
    LOG.debug("Using user: \"" + user + "\" with name " + user.getName());
  }

  User userEntry = createUserEntry(user);
  if (LOG.isDebugEnabled()) {
    LOG.debug("User entry: \"" + userEntry.toString() + "\"");
  }

  subject.getPrincipals().add(userEntry);
  return true;
}

private User createUserEntry(Principal user) throws LoginException {
  try {
    return new User(user.getName());
  } catch (Exception e) {
    throw (LoginException)(new LoginException(e.toString()).initCause(e));
  }
}

