  private synchronized int readWithStrategy(ReaderStrategy strategy, int off, int len) throws IOException {
    dfsClient.checkOpen();
    if (closed.get()) {
      throw new IOException("Stream closed");
    }
    Map<ExtendedBlock,Set<DatanodeInfo>> corruptedBlockMap 
      = new HashMap<ExtendedBlock, Set<DatanodeInfo>>();
    failures = 0;
    if (pos >= getFileLength()) {
      return -1;
    }
    int retries = 2;
    while (retries > 0) {
      try {
        updateBlockInfoIfNecessary();
        int realLen = computeRealReadLength(len);
        int result = readBuffer(strategy, off, realLen, corruptedBlockMap);
        if (result >= 0) {
          pos += result;
        } else {
          throw new IOException("Unexpected EOS from the reader");
        }
        if (dfsClient.stats != null) {
          dfsClient.stats.incrementBytesRead(result);
        }
        return result;
      } catch (ChecksumException ce) {
        throw ce;            
      } catch (IOException e) {
        if (retries == 1) {
          DFSClient.LOG.warn("DFS Read", e);
        }
        blockEnd = -1;
        if (currentNode != null) {
          addToDeadNodes(currentNode);
        }
        retries--;
        if (retries == 0) {
          throw e;
        }
      } finally {
        reportCheckSumFailure(corruptedBlockMap, 
            currentLocatedBlock.getLocations().length);
      }
    }
    return -1;
  }

  private void updateBlockInfoIfNecessary() throws IOException {
    if (pos > blockEnd || currentNode == null) {
      currentNode = blockSeekTo(pos);
    }
  }

  private int computeRealReadLength(int len) {
    long availableInBlock = blockEnd - pos + 1L;
    int realLen = (int) Math.min(len, availableInBlock);
    synchronized(infoLock) {
      if (locatedBlocks.isLastBlockComplete()) {
        long availableInFile = locatedBlocks.getFileLength() - pos;
        realLen = (int) Math.min(realLen, availableInFile);
      }
    }
    return realLen;
  }
