/**
 * Try to find a suitable datanode using network topology while falling back
 * to existing nodes in the same rack or any node in the cluster.
 *
 * @param dnId the original datanode ID parsed from the address
 * @return a suitable DatanodeDescriptor or null if none found
 */
private DatanodeDescriptor findNodeByNetworkTopology(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

  // If the current cluster doesn't contain the node, fallback to
  // something machine local and then rack local.
  List<Node> rackNodes = getNetworkTopology()
                             .getDatanodesInRack(networkLocation);
  if (rackNodes == null || rackNodes.isEmpty()) {
    return (DatanodeDescriptor) getNetworkTopology()
                                   .chooseRandom(NodeBase.ROOT);
  }

  // Try something machine local.
  for (Node rackNode : rackNodes) {
    if (((DatanodeDescriptor) rackNode).getIpAddr().equals(dnId.getIpAddr())) {
      return (DatanodeDescriptor) rackNode;
    }
  }

  // Try something rack local.
  return (DatanodeDescriptor) rackNodes
      .get(DFSUtil.getRandom().nextInt(rackNodes.size()));
}


