private boolean chooseProxySource() {
  final DatanodeInfo targetDN = target.getDatanodeInfo();

  if (isSourceAndTargetSameAndUsable()) {
    return true;
  }

  if (cluster.isNodeGroupAware()) {
    StorageGroup location = findBestLocation(
        block.getLocations(), 
        loc -> cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN));
    if (location != null && addTo(location)) {
      return true;
    }
  }

  StorageGroup location = findBestLocation(
      block.getLocations(), 
      loc -> cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN));
  if (location != null && addTo(location)) {
    return true;
  }

  for (StorageGroup loc : block.getLocations()) {
    if (addTo(loc)) {
      return true;
    }
  }
  return false;
}

private boolean isSourceAndTargetSameAndUsable() {
  if (!source.getDatanodeInfo().equals(target.getDatanodeInfo())) {
    return false;
  }
  return addTo(source);
}

private StorageGroup findBestLocation(
    List<StorageGroup> locations, 
    LocationPredicate predicate) {
  for (StorageGroup loc : locations) {
    if (predicate.test(loc)) {
      return loc;
    }
  }
  return null;
}

@FunctionalInterface
private interface LocationPredicate {
  boolean test(StorageGroup location);
}

