  private void recvMappingTables() throws IOException {
    final boolean[] inUse = this.data.inUse;
    int inUse16 = 0;

    for (int i = 0; i < 16; i++) {
      if (bsGetBit()) {
        inUse16 |= 1 << i;
      }
    }

    for (int i = 256; --i >= 0;) {
      inUse[i] = false;
    }

