    makeMaps();
  }

  private void recvSelectors() throws IOException {
    final byte[] selector = this.data.selector;
    final byte[] selectorMtf = this.data.selectorMtf;
    final byte[] pos = this.data.recvDecodingTables_pos;

    final int nSelectors = (int) bsR(15);

    for (int i = 0; i < nSelectors; i++) {
      int j = 0;
      while (bsGetBit()) {
        j++;
      }
      selectorMtf[i] = (byte) j;
    }

    for (int v = N_GROUPS; --v >= 0;) {
      pos[v] = (byte) v;
    }

    for (int i = 0; i < nSelectors; i++) {
      int v = selectorMtf[i] & 0xff;
      final byte tmp = pos[v];
      while (v > 0) {
        pos[v] = pos[v - 1];
        v--;
      }
      pos[0] = tmp;
      selector[i] = tmp;
    }
  }

