  /**
   * Validate transaction ID and log discrepancy if needed.
   * Returns -1 if the transaction should be skipped.
   */
  private long validateAndLogTransactionId(FSEditLogOp op, long expectedTxId,
      MetaRecoveryContext recovery, long numEdits, EditLogInputStream in) {
    if (!op.hasTransactionId()) {
      return expectedTxId;
    }

    long actualTxId = op.getTransactionId();

    if (actualTxId > expectedTxId) { 
      MetaRecoveryContext.editLogLoaderPrompt("There appears " +
          "to be a gap in the edit log.  We expected txid " +
          expectedTxId + ", but got txid " +
          actualTxId + ".", recovery, "ignoring missing " +
          " transaction IDs");
    } else if (actualTxId < expectedTxId) { 
      MetaRecoveryContext.editLogLoaderPrompt("There appears " +
          "to be an out-of-order edit in the edit log.  We " +
          "expected txid " + expectedTxId + ", but got txid " +
          actualTxId + ".", recovery,
          "skipping the out-of-order edit");
      return -1L;
    }

    return actualTxId;
  }

private boolean shouldAbortOnBlockEnd() throws IOException {
  this.currentState = STATE.EOF;
  complete();
  return true;
}

private boolean isBlockStartMarker(int magic0, int magic1, int magic2, int magic3, int magic4, int magic5) {
  return magic0 == 0x31 &&
      magic1 == 0x41 &&
      magic2 == 0x59 &&
      magic3 == 0x26 &&
      magic4 == 0x53 &&
      magic5 == 0x59;
}

private boolean isEndOfStreamMarker(int magic0, int magic1, int magic2, int magic3, int magic4, int magic5) {
  return magic0 == 0x17 &&
      magic1 == 0x72 &&
      magic2 == 0x45 &&
      magic3 == 0x38 &&
      magic4 == 0x50 &&
      magic5 == 0x90;
}

private void initBlock() throws IOException {
  if (this.readMode == READ_MODE.BYBLOCK) {
    this.storedBlockCRC = bsGetInt();
    this.blockRandomised = bsR(1) == 1;

    if (this.data == null) {
      this.data = new Data(this.blockSize100k);
    }

    getAndMoveToFrontDecode();

    this.crc.initialiseCRC();
    this.currentState = STATE.START_BLOCK_STATE;
    return;
  }

  char magic0 = bsGetUByte();
  char magic1 = bsGetUByte();
  char magic2 = bsGetUByte();
  char magic3 = bsGetUByte();
  char magic4 = bsGetUByte();
  char magic5 = bsGetUByte();

  if (isEndOfStreamMarker(magic0, magic1, magic2, magic3, magic4, magic5)) {
    if (shouldAbortOnBlockEnd()) {
      return;
    }
  } else if (!isBlockStartMarker(magic0, magic1, magic2, magic3, magic4, magic5)) {
    this.currentState = STATE.EOF;
    throw new IOException("bad block header");
  } else {
    this.storedBlockCRC = bsGetInt();
    this.blockRandomised = bsR(1) == 1;

    if (this.data == null) {
      this.data = new Data(this.blockSize100k);
    }

    getAndMoveToFrontDecode();

    this.crc.initialiseCRC();
    this.currentState = STATE.START_BLOCK_STATE;
  }
}

