class ModelFormBaseTest(TestCase):
    def test_base_form(self):
        self.assertEqual(_get_form_field_names(BaseCategoryForm),
                         ['name', 'slug', 'url'])

    def test_no_model_class(self):
        class NoModelModelForm(forms.ModelForm):
            pass
