/**
 * Copies the state from the source theme to this theme.
 * This method handles deep copying of mutable fields to ensure
 * true cloning semantics without relying on clone() implementations.
 *
 * @param source  the source theme (<code>null</code> not permitted).
 */
private void copyStateFrom(StandardChartTheme source) {
    // Deep copy of DrawingSupplier
    if (source.drawingSupplier != null) {
        if (source.drawingSupplier instanceof PublicCloneable) {
            PublicCloneable pc = (PublicCloneable) source.drawingSupplier;
            try {
                this.drawingSupplier = (DrawingSupplier) pc.clone();
            }
            catch (CloneNotSupportedException e) {
                // Should never happen as PublicCloneable mandates clone() support
                throw new RuntimeException(e);
            }
        } else {
            this.drawingSupplier = source.drawingSupplier;
        }
    }

    // Deep copy of RectangleInsets (immutable, so safe reference sharing)
    this.axisOffset = source.axisOffset;

    // Deep copy of Font objects
    this.extraLargeFont = copyFont(source.extraLargeFont);
    this.largeFont = copyFont(source.largeFont);
    this.regularFont = copyFont(source.regularFont);
    this.smallFont = copyFont(source.smallFont);

    // Deep copy of Paint objects where needed (transient fields handled by serialization)
    // For non-transient mutable paints, use readObject/writeObject
    // Since all Paint fields are transient except for shadowGenerator,
    // we only need to handle shadowGenerator carefully
    if (source.shadowGenerator != null) {
        this.shadowGenerator = new DefaultShadowGenerator(
            source.shadowGenerator.getPaint(),
            source.shadowGenerator.getOffsetX(),
            source.shadowGenerator.getOffsetY(),
            source.shadowGenerator.getBlurRadius(),
            source.shadowGenerator.getOpacity()
        );
    }

    // All other fields are primitives, immutable types, or have safe sharing
    // BarPainter, XYBarPainter, PieLabelLinkStyle, etc. can be shared
}

/**
 * Creates a copy of the specified font.
 *
 * @param font  the font to copy (<code>null</code> not permitted).
 *
 * @return A copy of the font.
 */
private Font copyFont(Font font) {
    return new Font(font.getName(), font.getStyle(), font.getSize());
}


